mapper.select:


    d.del_flag = '0'

        and d.batch_id = #{batchId}


        and d.batch_no like concat('%', #{batchNo}, '%')


        and d.stat_month = #{statMonth}


        and d.dispatch_enterprise_id = #{dispatchEnterpriseId}


        and d.person_name like concat('%', #{personName}, '%')


        and d.att_check = #{attCheck}


        and d.pay_status = #{payStatus}


        and d.region_code like concat(#{regionCode}, '%')

    ${params.regionDataScope}
    ${params.enterpriseDataScope}

order by d.stat_month desc, d.detail_id desc

select d.net_amount from t_salary_detail d where d.del_flag = '0' and d.person_id = #{personId}
and d.stat_month = #{statMonth}
order by d.stat_month desc, d.detail_id desc limit 1

where d.del_flag = '0' and d.person_id = #{personId}
and d.stat_month like concat(#{yearPrefix}, '%')
order by d.stat_month desc, d.detail_id desc


where d.del_flag = '0'
  and d.person_id = #{personId}
  and d.stat_month = #{statMonth}
order by d.detail_id desc
limit 1
